import RNA, random, multiprocessing as mp, time
target="(((((.(..((((.(..((((.(..((((.(..(((((((.((((((.(((((.((((((.(((.((((((....))))))..)))).)))).))))).)))))).)))))))).)..)))).)..)))).)..)))).)..)))))"
n=len(target)
st=[]; pairs=[-1]*n
for i,c in enumerate(target):
    if c=='(': st.append(i)
    elif c==')': j=st.pop(); pairs[i]=j; pairs[j]=i
def make_start():
    s=['A']*n
    for i in range(n):
        if pairs[i]!=-1 and i<pairs[i]:
            j=pairs[i]
            # alternate G-C / C-G with some AU
            r=random.random()
            if r<0.6: s[i],s[j]='G','C'
            elif r<0.8: s[i],s[j]='C','G'
            else: s[i],s[j]='A','U'
    return ''.join(s)
def worker(seed):
    random.seed(seed)
    for _ in range(150):
        start=make_start()
        seq,d = RNA.inverse_fold(start, target)
        if d==0 and RNA.fold_compound(seq).mfe()[0]==target:
            return seq
    return None
if __name__=='__main__':
    t0=time.time()
    found=[None]
    with mp.Pool(32) as p:
        for r in p.imap_unordered(worker, range(256)):
            if r:
                print('SOLVED',r); p.terminate(); break
    print('elapsed',time.time()-t0)
